package com.motionecosystem.participantmeasurements;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.Instant; import java.util.UUID;
@Entity @Table(schema="participant_measurement", name="participant_measurement") class ParticipantMeasurement {
 @Id UUID id; @Column(nullable=false) UUID participantId; @Column(name="appointment_id") UUID appointmentId; @Column(nullable=false) String metricCode; @Column(nullable=false, precision=19, scale=6) BigDecimal value; @Column(nullable=false) String unit; @Column(nullable=false) String measurementMethod; @Column(nullable=false) Instant measuredAt; @Column(length=500) String note; @Column(nullable=false) UUID recordedByAccountId; @Column(nullable=false) Instant recordedAt; @Column(nullable=false) String source; @Column(nullable=false,length=120) String idempotencyKey;
 protected ParticipantMeasurement(){} ParticipantMeasurement(UUID id,UUID p,UUID appointmentId,String metric,BigDecimal value,String unit,String method,Instant measured,String note,UUID recorder,Instant recorded,String key){this.id=id;participantId=p;this.appointmentId=appointmentId;metricCode=metric;this.value=value;this.unit=unit;measurementMethod=method;measuredAt=measured;this.note=note;recordedByAccountId=recorder;recordedAt=recorded;source=appointmentId==null?"SPECIALIST_MANUAL":"APPOINTMENT_CLOSEOUT";idempotencyKey=key;}
 UUID id(){return id;} UUID participantId(){return participantId;} UUID appointmentId(){return appointmentId;} String metricCode(){return metricCode;} BigDecimal value(){return value;} String unit(){return unit;} String measurementMethod(){return measurementMethod;} Instant measuredAt(){return measuredAt;} String note(){return note;} UUID recordedByAccountId(){return recordedByAccountId;} Instant recordedAt(){return recordedAt;} String source(){return source;}
}
